#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

void printBinary(int n) {
    for (int i = 7; i >= 0; i--) {
        printf("%d", (n >> i) & 1);
    }
}

int main() {
    int header;
    if (scanf("%d", &header) != 1) return 0;

    char op[100];
    int toggleDone = 0, setDone = 0, clearDone = 0;

    while (scanf("%99s", op) == 1) {
        if (strcmp(op, "Toggle") == 0) {
            char temp[50];
            scanf("%s %s", temp, temp);
            header ^= 1;
            if (!toggleDone) {
                printf("New Header in Decimal: %d\n", header);
                printf("New Header in Binary: ");
                printBinary(header);
                printf("\n");
                toggleDone = 1;
            }
        } else if (strcmp(op, "Set") == 0) {
            char temp[50];
            scanf("%s %s %s %s", temp, temp, temp, temp);
            header |= 2;
            if (!setDone) {
                printf("New Header in Decimal: %d\n", header);
                printf("New Header in Binary: ");
                printBinary(header);
                printf("\n");
                setDone = 1;
            }
        } else if (strcmp(op, "Clear") == 0) {
            char temp[50];
            scanf("%s %s %s", temp, temp, temp);
            header &= ~(1 << 2);
            if (!clearDone) {
                printf("New Header after clearing encryption status: %d\n", header);
                printf("New Header in Binary: ");
                printBinary(header);
                printf("\n");
                clearDone = 1;
            }
        } else if (strcmp(op, "Check") == 0) {
            char temp[50];
            scanf("%s %s %s", temp, temp, temp);
            int error = (header >> 3) & 1;
            printf("Error Detected: %s\n", error ? "Yes" : "No");
        } else if (strcmp(op, "Shift") == 0) {
            char temp[50];
            scanf("%s %s %s", temp, temp, temp);
            header <<= 1;
            printf("Header after Left Shift by 1 Bit: %d\n", header);
            printf("New Header in Binary: ");
            printBinary(header);
            printf("\n");
        }
    }

    return 0;
}
